string countAndSay(int n) {
    string s = "1";
    for (int i = 1; i < n; i++) {
        string next;
        for (int j = 0; j < s.size(); ) {
            int k = j;
            while (k < s.size() && s[k] == s[j]) k++;
            next += to_string(k - j) + s[j];
            j = k;
        }
        s = next;
    }
    return s;
}
// RLE编码：内层while计数 | to_string(cnt)+字符 | 迭代n-1次
